                post_hook={
                    "sql": "Create or replace table prolicious-wh.Maplemonk.Prolicious_PANDL as with pandl as ( select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, customer_id, SHOP_NAME, coalesce(sc.marketplace,mc.marketplace) marketplace, coalesce(sc.CHANNEL,mc.channel) CHANNEL, SOURCE, cast(ORDER_ID as string) ORDER_ID, cast(sc.reference_code as string)reference_code , PHONE, sc.NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, sc.SKU AS SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, coalesce(sc.Order_Date,mc.date) as Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, 0 as SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, sc.SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, cast(PAYMENT_GATEWAY as string) as PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, coalesce(sc.SKU_CODE,p.skucode) AS SKU_CODE, PRODUCT_NAME_FINAL, coalesce(sc.PRODUCT_CATEGORY) AS Product_Category, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, b2b_customer, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, flavour, subcat_1, subcat_2, pack_type, Cat, 0 AS Return_Fee, 0 AS pick_pack_Charges, 0 as logistics_cost, coalesce(smc.mrp,p.MRP) * (ifnull(QUANTITY,0)) AS MRP, coalesce(smc.cogs,p.cost) * (ifnull(QUANTITY,0)) AS COGS, CASE WHEN upper(sc.SHOP_NAME) LIKE \'%SELLER%\' THEN SAFE_DIVIDE( IFNULL(mc.spend, 0) * SAFE_DIVIDE( SUM(CASE WHEN upper(sc.SHOP_NAME) LIKE \'%SELLER%\' THEN sc.SELLING_PRICE ELSE 0 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')), SUM(CASE WHEN (upper(sc.SHOP_NAME) LIKE \'%SELLER%\') OR (upper(sc.SHOP_NAME) LIKE \'%B2B%\' AND upper(sc.b2b_customer) LIKE \'%VENDOR%\') THEN sc.SELLING_PRICE ELSE 0 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')) ), COUNT(CASE WHEN upper(sc.SHOP_NAME) LIKE \'%SELLER%\' THEN 1 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')) ) WHEN (upper(sc.SHOP_NAME) LIKE \'%B2B%\' AND upper(sc.b2b_customer) LIKE \'%VENDOR%\') THEN SAFE_DIVIDE( IFNULL(mc.spend, 0) * SAFE_DIVIDE( SUM(CASE WHEN (upper(sc.SHOP_NAME) LIKE \'%B2B%\' AND upper(sc.b2b_customer) LIKE \'%VENDOR%\') THEN sc.SELLING_PRICE ELSE 0 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')), SUM(CASE WHEN (upper(sc.SHOP_NAME) LIKE \'%SELLER%\') OR (upper(sc.SHOP_NAME) LIKE \'%B2B%\' AND upper(sc.b2b_customer) LIKE \'%VENDOR%\') THEN sc.SELLING_PRICE ELSE 0 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')) ), COUNT(CASE WHEN (upper(sc.SHOP_NAME) LIKE \'%B2B%\' AND upper(sc.b2b_customer) LIKE \'%VENDOR%\') THEN 1 END) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), coalesce(upper(mc.channel), \'AMAZON\')) ) ELSE SAFE_DIVIDE( IFNULL(mc.spend, 0), COUNT(*) OVER(PARTITION BY coalesce(sc.Order_Date, mc.date), upper(coalesce(sc.CHANNEL, mc.channel, \'\')), upper(coalesce(sc.marketplace, mc.marketplace, \'\'))) ) END AS Marketing_Spend, rc.reference_code as return_reference_code, IFNULL(rc.TOTAL_RETURN_AMOUNT,0) AS TOTAL_RETURN_AMOUNT, IFNULL(rc.TOTAL_RETURN_TAX, 0) AS RETURN_TAX, ifnull(rc.total_returned_quantity,0) AS RETURNED_QUANTITY from maplemonk.prolicious_wh_sales_consolidated sc left join (select * from ( select reference_code, saleorderitemcode, marketplace, TOTAL_RETURN_AMOUNT, TOTAL_RETURN_TAX, total_returned_quantity, row_number() over (partition by reference_code,saleorderitemcode order by return_date desc) rw from maplemonk.prolicious_wh_returns_consolidated ) where rw = 1 ) rc on lower(sc.reference_code) = lower(rc.reference_code) AND lower(sc.saleorderitemcode) = lower(rc.saleorderitemcode) left join (select * from ( select coalesce(cast(c.mrp as float64),cast(s.mrp as float64)) as mrp, case when cogs = \'#N/A\' then null else cast(cogs as float64) end as cogs, upper(trim(sku_code)) as old_sku, upper(s.master_sku) as sku, row_number() over (partition by upper(trim(sku_code)) order by 1 desc) as rw from `Maplemonk.Prolicious_GS_SKU_MRP_COGS` c left join maplemonk.final_latest_sku_master s on upper(s.Old_Sku_Name) = upper(trim(sku_code)) ) where rw = 1 ) smc on lower(smc.sku) = lower(sc.commonsku) left join (select * from (select sku as skucode ,CAST(mrp AS FLOAT64) AS MRP ,CAST(cost AS FLOAT64) AS cost ,size ,colour ,tax_rate ,Product_Name as name ,category_name as category ,row_number() over (partition by SKU order by 1) rw from maplemonk.EasyEcom_Prolicious_Easyecom_product_master ) where rw = 1 ) p on lower(sc.sku) = lower(p.skucode) full outer join ( select date, case when upper(ifnull(channel,\'\')) like \'%AMAZON%\' then \'AMAZON\' when upper(ifnull(channel,\'\')) like \'%FLIPKART%\' then \'FLIPKART\' when upper(ifnull(channel,\'\')) like \'%SWIGGY%\' then \'SWIGGY\' when upper(ifnull(channel,\'\')) like \'%BLINKIT%\' then \'BLINKIT\' when upper(ifnull(channel,\'\')) like \'%FACEBOOK%\' then \'META\' else upper(ifnull(channel,\'\')) end as channel, case when upper(ifnull(channel,\'\')) like \'%AMAZON%\' then \'AMAZON\' when upper(ifnull(channel,\'\')) like \'%FLIPKART%\' then \'FLIPKART\' when upper(ifnull(channel,\'\')) like \'%SWIGGY%\' then \'SWIGGY\' when upper(ifnull(channel,\'\')) like \'%BLINKIT%\' then \'BLINKIT\' when upper(ifnull(channel,\'\')) like any (\'%FACEBOOK%\',\'%GOOGLE%\') then \'WEBSITE\' else upper(ifnull(channel,\'\')) end as marketplace, sum(ifnull(spend,0)) spend from maplemonk.prolicious_wh_MARKETING_CONSOLIDATED where channel is not null group by 1,2,3 )mc on sc.order_date = mc.date and CASE WHEN upper(SHOP_NAME) IN (\'SHOPIFY\', \'WEBSITE\') THEN upper(sc.channel) WHEN upper(b2b_customer) LIKE \'%SWIGGY%\' THEN \'SWIGGY\' WHEN upper(shop_name) LIKE \'%BLINKIT%\' THEN \'BLINKIT\' WHEN upper(SHOP_NAME) LIKE \'%FLIPKART%\' OR upper(b2b_customer) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN (upper(SHOP_NAME) LIKE \'%B2B%\' AND upper(b2b_customer) LIKE \'%VENDOR%\') or upper(SHOP_NAME) LIKE \'%SELLER%\' THEN \'AMAZON\' END = upper(mc.channel) and upper(mc.marketplace) = CASE WHEN upper(SHOP_NAME) IN (\'SHOPIFY\', \'WEBSITE\') THEN \'WEBSITE\' WHEN upper(b2b_customer) LIKE \'%SWIGGY%\' THEN \'SWIGGY\' WHEN upper(shop_name) LIKE \'%BLINKIT%\' THEN \'BLINKIT\' WHEN upper(SHOP_NAME) LIKE \'%FLIPKART%\' OR upper(b2b_customer) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN (upper(SHOP_NAME) LIKE \'%B2B%\' AND upper(b2b_customer) LIKE \'%VENDOR%\') or upper(SHOP_NAME) LIKE \'%SELLER%\' THEN \'AMAZON\' ELSE NULL END ), mapped_pandl AS ( SELECT *, CASE WHEN upper(SHOP_NAME) IN (\'SHOPIFY\', \'WEBSITE\') THEN \'WEBSITE\' WHEN upper(b2b_customer) LIKE \'%SWIGGY%\' THEN \'SWIGGY\' WHEN upper(shop_name) LIKE \'%BLINKIT%\' THEN \'BLINKIT\' WHEN upper(SHOP_NAME) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN upper(SHOP_NAME) LIKE \'%SELLER%\' THEN \'AMAZON SELLER\' WHEN (upper(SHOP_NAME) LIKE \'%B2B%\' AND upper(b2b_customer) LIKE \'%VENDOR%\') THEN \'AMAZON VENDOR\' ELSE NULL END AS Marketplace_Name FROM pandl ) SELECT * FROM mapped_pandl WHERE Marketplace_Name IS NOT NULL ;",
                    "transaction": true
